const ctx = canvas.getContext("2d");
canvas.width = 400;
canvas.height = 400;

// Render function
function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, length, 0, 2 * PI);
  ctx.fillStyle = "black";
  ctx.fill();

  // Calculate new angle and velocity
  let acceleration = -GRAVITY / length * Math.sin(angle);
  velocity += acceleration * ANGLE_STEP;
  angle += velocity * ANGLE_STEP;

  // Draw pendulum
  ctx.beginPath();
  ctx.moveTo(canvas.width / 2, canvas.height / 2);
  ctx.lineTo(canvas.width / 2 + length * Math.sin(angle), canvas.height / 2 - length * Math.cos(angle));
  ctx.stroke();

  // Update UI with current angle and velocity
  document.getElementById("angle").textContent = `Angle: ${angle.toFixed(2)} rad`;
  document.getElementById("velocity").textContent = `Velocity: ${velocity.toFixed(2)} m/s`;

  // Check if pendulum has stopped
